local t = require("tests.run")
local cm = require("lgen.color_math")
local fixer = require("lgen.fixer")
local lgen = require("lgen")
local rgb = cm.hex_to_rgb

t.test("CVD simulations match published linearRGB projection fixtures", function()
  -- Independently evaluated DaltonLens filters, not expectations generated by lgen.
  -- https://github.com/DaltonLens/libDaltonLens/blob/master/svg/cvd_svg_filters.html
  local fixtures = {
    {"protan", "#ff0000", 0.363791114549, 0.363791114549, 0.055716902621},
    {"deutan", "#ff0000", 0.575151476045, 0.575151476045, 0},
    {"protan", "#0000ff", 0, 0, 1},
    {"deutan", "#0000ff", 0, 0, 1},
    {"protan", "#336699", 0.384113281204, 0.384113281204, 0.599617779740},
    {"deutan", "#336699", 0.355694913820, 0.355694913820, 0.601874086064},
    -- Red and green select opposite Brettel half-planes.
    {"tritan", "#ff0000", 1, 0, 0.307622453948},
    {"tritan", "#00ff00", 0.484517964126, 0.919056435751, 1},
    {"tritan", "#0000ff", 0, 0.375376377470, 0.528102016060},
    {"tritan", "#336699", 0.128302758694, 0.421796861364, 0.501515397527},
  }
  for _, fixture in ipairs(fixtures) do
    local actual = cm.sim_cvd(rgb(fixture[2]), fixture[1])
    t.assert_near(actual.r, fixture[3], 1e-9)
    t.assert_near(actual.g, fixture[4], 1e-9)
    t.assert_near(actual.b, fixture[5], 1e-9)
  end
end)

t.test("agent audit results identify models and distinguish style policy", function()
  local diag = assert(lgen.audit_string("- bg: #000000\n- red: #aaaaaa\n"))
  t.assert_eq(diag.metrics.models.cvd.protan, "vienot1999-srgb-daltonlens")
  t.assert_eq(diag.metrics.models.cvd.tritan, "brettel1997-srgb-daltonlens")
  t.assert_eq(diag.metrics.models.gamut, "oklch-chroma-reduction-v1")
  t.assert_eq(diag.metrics.policy.version, "3")
  for _, item in ipairs(diag.warns) do
    if item.code == "MUTED_COLOR" then
      t.assert_eq(item.category, "style")
      t.assert_eq(item.basis, "project-policy")
      return
    end
  end
  error("Expected muted style diagnostic")
end)

t.test("comment desaturation retains readable serialized contrast", function()
  local bg = rgb("#666666")
  local out = assert(fixer.desaturate_comment(rgb("#ffddee"), bg))
  t.assert_true(math.abs(cm.apca(rgb(out), bg)) >= 48)
  t.assert_true(cm.wcag_contrast(rgb(out), bg) >= 2.5)
  t.assert_true(cm.oklab_to_oklch(cm.rgb_to_oklab(rgb(out))).C <= 0.045)
end)

t.test("CVD adjustments check the quantized projection and retain text contrast", function()
  for _, pair in ipairs({
    {"#111111", "#b08070", "#90a070"},
    {"#ffffff", "#111111", "#111111"},
  }) do
    local bg, red, green = rgb(pair[1]), rgb(pair[2]), rgb(pair[3])
    for _, kind in ipairs({"protan", "deutan"}) do
      local out = assert(fixer.adjust_cvd_pair(green, red, bg, kind))
      local de = cm.delta_e_ok(cm.rgb_to_oklab(cm.sim_cvd(rgb(out), kind)),
        cm.rgb_to_oklab(cm.sim_cvd(red, kind)))
      t.assert_true(de >= 0.085)
      t.assert_true(math.abs(cm.apca(rgb(out), bg)) >= 45)
      t.assert_true(cm.wcag_contrast(rgb(out), bg) >= 3)
    end
  end
end)

t.test("diff preview uses the same green slot as the CVD audit", function()
  local preview = lgen.reporter.render_syntax_preview({
    [1]=rgb("#ff0000"), [2]=rgb("#00ff00"), [10]=rgb("#0000ff"),
  })
  for line in preview:gmatch("[^\n]+") do
    if line:find("diff_added", 1, true) then
      t.assert_true(line:find("\27[38;2;0;255;0m", 1, true) ~= nil)
      return
    end
  end
  error("No diff addition rendered")
end)

t.test("white bright-pair inversions are included in the audit", function()
  local diag = assert(lgen.audit_string("- bg: #000000\n- white: #ffffff\n- bright_white: #cccccc\n"))
  local found = false
  for _, item in ipairs(diag.warns) do
    if item.code == "INVERTED_BRIGHT_PAIR" and item.context.norm == 7 and item.context.bright == 15 then
      found = true
    end
  end
  t.assert_true(found)
end)

t.test("neutral accents do not get hue-sector warnings", function()
  local diag = assert(lgen.audit_string("- bg: #000000\n- red: #aaaaaa\n"))
  for _, item in ipairs(diag.warns) do
    t.assert_true(item.code ~= "HUE_SECTOR_MISMATCH")
  end
end)

t.test("accent balancing respects light themes and preserves contrast", function()
  local out = assert(fixer.balance_accent_lightness(rgb("#103050"), 0.4, rgb("#ffffff")))
  t.assert_near(cm.rgb_to_oklab(rgb(out)).L, 0.4, 0.003)
  t.assert_true(math.abs(cm.apca(rgb(out), rgb("#ffffff"))) >= 45)
  local dark = assert(fixer.balance_accent_lightness(rgb("#103050"), 0.4, rgb("#000000")))
  t.assert_true(math.abs(cm.apca(rgb(dark), rgb("#000000"))) >= 45)
  t.assert_true(out ~= dark)
end)

t.test("strict contrast suggestions satisfy both audit criteria", function()
  local plan = assert(lgen.fix_string("- bg: #ffffff\n- blue: #666666\n", {
    strictness="strict", ignore={"MUTED_COLOR", "HUE_SECTOR_MISMATCH"},
  }))
  t.assert_eq(#plan.after.fails, 0)
  t.assert_eq(#plan.after.warns, 0)
  local out = assert(lgen.markdown_parser.parse(plan.content).palette[4])
  t.assert_true(cm.wcag_contrast(out, rgb("#ffffff")) >= 7)
  t.assert_true(math.abs(cm.apca(out, rgb("#ffffff"))) >= 75)
end)

t.test("contrast fixes search both directions and assess the returned hex", function()
  for _, example in ipairs({
    {"#666666", "#666666", 60},
    {"#09065b", "#111111", 60},
  }) do
    local out = assert(fixer.adjust_contrast(rgb(example[1]), rgb(example[2]), example[3]))
    t.assert_true(math.abs(cm.apca(rgb(out), rgb(example[2]))) >= example[3])
  end
  local plan = assert(lgen.fix_string("- bg: #666666\n- fg: #666666\n"))
  t.assert_eq(#plan.after.fails, 0)
  local impossible, err = fixer.adjust_contrast(rgb("#333333"), rgb("#111111"), 200)
  t.assert_eq(impossible, nil)
  t.assert_eq(err.code, "UNREACHABLE_CONTRAST")
end)

t.test("WCAG luminance uses the published sRGB coefficients", function()
  t.assert_near(cm.relative_luminance(rgb("#ff0000")), 0.2126, 1e-12)
  t.assert_near(cm.relative_luminance(rgb("#00ff00")), 0.7152, 1e-12)
  t.assert_near(cm.relative_luminance(rgb("#0000ff")), 0.0722, 1e-12)
  t.assert_near(cm.wcag_contrast(rgb("#ff0000"), rgb("#000000")), 5.252, 1e-12)
end)
